<?php
 declare(strict_types=1); namespace Sabberworm\CSS\Position; trait Position { protected $lineNumber; protected $columnNumber; public function getLineNumber() { return $this->lineNumber; } public function getLineNo() { $lineNumber = $this->getLineNumber(); return $lineNumber !== null ? $lineNumber : 0; } public function getColumnNumber() { return $this->columnNumber; } public function getColNo() { $columnNumber = $this->getColumnNumber(); return $columnNumber !== null ? $columnNumber : 0; } public function setPosition($lineNumber, $columnNumber = null) { $this->lineNumber = $lineNumber !== 0 ? $lineNumber : null; $this->columnNumber = $columnNumber; } } 